const std = @import("std");
const mem = std.mem;

pub fn translate(allocator: mem.Allocator, phrase: []const u8) mem.Allocator.Error![]u8 {
    const out = try allocator.alloc(u8, phrase.len * 2 + 1);
    var len: usize = 0;
    var first = true;
    var i: usize = 0;
    while (i < phrase.len) {
        while (i < phrase.len and phrase[i] == ' ') i += 1;
        if (i >= phrase.len) break;
        const start = i;
        while (i < phrase.len and phrase[i] != ' ') i += 1;
        const word = phrase[start..i];
        const translated = try translateWord(allocator, word);
        if (!first) {
            out[len] = ' ';
            len += 1;
        }
        first = false;
        for (translated) |c| {
            out[len] = c;
            len += 1;
        }
        allocator.free(translated);
    }
    const result = try allocator.realloc(out, len);
    return result;
}
```

